def find_Product(arr, n):
    # Dictionary to store the frequency of each element
    frequency = {}

    # Count the frequency of each element
    for i in range(n):
        if arr[i] in frequency:
            frequency[arr[i]] += 1
        else:
            frequency[arr[i]] = 1

    # Calculate the product of non-repeated elements
    result = 1
    for key in frequency:
        if frequency[key] == 1:
            result *= key

    return result

